def _confirmation_priority(self, *, paused: bool, preparing: bool, lp_exit: bool,
                           checked: set[int]) -> bool:
    """Service existing sample/reset deadlines before optional nonce users.

    This runs only AFTER saved-intent recovery and shared lifecycle/authority
    gates. No new journal namespace, signing path or on-chain exception is
    introduced. Cold discovery and time between checks retain normal queue
    fairness. A serial sender can still miss strict gaps under slow finality
    or several simultaneous windows; this is priority, never an SLA.
    """
    if self.rebalance_confirmation.version not in (1,2,3) or preparing or lp_exit:
        return False
    schedules = self.state.get(self._confirmation_namespace(),{})
    resets = self.state.get(CONFIRMATION_RESETS,{})
    clears = {key for key,record in self.state.get(CONFIRMATION_CLEARS,{}).items()
        if record['awaiting_healthy_read']}
    if not schedules and not resets and not clears:
        return False
    try: _,now = self._head()
    except (ValueError,RpcError):
        self._mark_known_confirmation_resets()
        raise
    if any(now < record['last_checked_at'] for record in schedules.values()):
        # A retreated head must not disguise an old deadline as future and
        # yield its nonce slot to optional work before raw reset handling.
        self._mark_known_confirmation_resets()
        raise RpcError('Confirmation priority chain clock retreated')
    deadlines = {key:0 for key in set(resets) | clears}
    for key,record in schedules.items():
        deadline = min(record['next_check_at'],record['last_checked_at']+CONFIRMATION_CHECK_SECONDS)
        if record['execute_after']:
            deadline = min(deadline,record['execute_after'])
        if paused or now >= deadline:
            deadlines[key] = min(deadlines.get(key,deadline),deadline)
    for key in sorted(deadlines,key=lambda key:(deadlines[key],int(key))):
        bucket = int(key)
        checked.add(bucket)
        try:
            _,fresh = self._head()
            if fresh < now: raise RpcError('Confirmation priority chain clock retreated')

confirmation = None
if keeper.rebalance_confirmation.version in (1,2,3):
    # Pending recovery must not acquire a dependency on a new policy read.
    # Otherwise validate the gate even before any bucket leaves cooldown.
    if keeper.state.get('pending') is not None:
        confirmation = {'schema':1,'state':'pending_recovery','last_observed':None,'last_error':None}
    else:
        confirmation = observe_confirmation_health(keeper)
        if confirmation['state']=='stopped': reasons.append('rebalance_confirmation_stopped')
        elif confirmation['state']=='incompatible_cadence': reasons.append('rebalance_confirmation_cadence_incompatible')
        elif confirmation['state']!='observed_this_cycle': reasons.append('rebalance_confirmation_unavailable')
# Recheck the existing anchor after the RPC calls; this is still a point-in-time observation.
keeper._validate_checkpoint()
return {'ok':not reasons,'reasons':reasons,'chain_id':keeper.chain,'head':head,'preparation_active':preparing,'canonical_state':lifecycle,

function quoteCandidate(PoolKey calldata key, bool direction, uint256 amount) external returns (uint256 output,MarketState memory state) {
    if (msg.sender != address(this) || amount == 0 || amount > uint256(uint128(type(int128).max))) revert Unauthorized();
    bytes memory payload = abi.encode(key,direction,amount);
    pendingQuoteHash = keccak256(payload);
    try poolManager.unlock(payload) returns (bytes memory) { revert InvalidState(); }
    catch (bytes memory reason) {
        pendingQuoteHash = bytes32(0);
        bytes4 selector;
        if (reason.length == 196) assembly ("memory-safe") { selector := mload(add(reason,32)) }
        if (selector != QuoteResult.selector) revert InvalidState();
        bytes memory result=new bytes(192);
        assembly ("memory-safe") { mcopy(add(result,32),add(reason,36),192) }
        (output,state)=abi.decode(result,(uint256,MarketState));
        if (output == 0 || state.sqrtPriceX96<TickMath.MIN_SQRT_PRICE || state.sqrtPriceX96>=TickMath.MAX_SQRT_PRICE ||
            state.tick<TickMath.MIN_TICK || state.tick>=TickMath.MAX_TICK || state.lpFee!=key.fee ||
            (state.protocolFee & 0xfff)>1000 || state.protocolFee>>12>1000)revert InvalidState();
    }
}
